import assert from 'node:assert/strict';import {mkdir,writeFile} from 'node:fs/promises';import {chromium} from './black-gold-playwright.mjs';
const out='/tmp/ko-card-lore-battle';await mkdir(out,{recursive:true});const browser=await chromium.launch();const results=[];
try{for(const [width,height]of [[390,844],[844,390],[1440,900]]){const page=await browser.newPage({viewport:{width,height},isMobile:width<1000,hasTouch:width<1000});await page.route('**/api/**',r=>r.fulfill({json:{frames:[],cards:[],items:[]}}));await page.goto('http://127.0.0.1:5186/qa/black-gold-board.html');await page.locator('.ko-game-shell').waitFor();await page.evaluate(async()=>{const {boardFixture,definitions}=await import('/qa/black-gold-fixture.ts');const {generateCardInstance}=await import('/src/game/index.ts');const d={...definitions.find(c=>c.cardType==='WRESTLER'),id:'lore-battle',name:'전투 소개 확인',lore:'필드에서도 읽을 수 있는 이야기.\n두 번째 문단.',abilities:[],rulesText:'효과 없음'};const s=boardFixture();s.cardPool=[...definitions,d];s.events=[];s.players[0].board=[{...generateCardInstance(d,{instanceId:'lore-battle-instance'}),boardSlot:0,enteredThisTurn:false},null,null,null];window.dispatchEvent(new CustomEvent('ko-qa-load-state',{detail:{state:s,definitions:s.cardPool}}));});const info=page.locator('.ko-player-board-row [data-touch-inspect-trigger]').first();if(width<1000)await info.tap();else await info.click();const panel=page.getByRole('complementary',{name:'상세정보',exact:true});await panel.getByTestId('card-introduction').waitFor();assert.match(await panel.getByTestId('card-introduction').innerText(),/필드에서도 읽을 수 있는 이야기/);await panel.getByTestId('card-introduction').scrollIntoViewIfNeeded();await page.screenshot({path:`${out}/battle-info-${width}.png`});results.push({width,height,realBattleInspector:true,introductionVisible:true});await page.close();}await writeFile(out+'/results.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));}finally{await browser.close()}
